                    return true
                }
                if (minute < end && isDaySet(schedule.daysMask, previousDayOfWeek)) {
                    return true
                }
            }
        }
        return false
    }

    private fun isDaySet(daysMask: Int, dayIndex: Int): Boolean {
        return (daysMask and (1 shl dayIndex)) != 0
    }
